<?php if($doneChapters<3): ?><div class="upload-lock" role="status"><strong>Naskah proposal belum dapat diunggah</strong><span>Bab 1–3 yang sudah disetujui Pembimbing 1: <?=$doneChapters?> dari 3. Setelah lengkap, unggah Bab 1–3 dalam satu file untuk Pembimbing 2.</span></div>
<?php elseif(!$formatDoc): ?><div class="upload-lock" role="status"><strong>Langkah berikutnya</strong><span>Gabungkan Bab 1–3 dalam satu file Word, lalu unggah sebagai <em><?=h(P2_FORMAT_DOC)?></em> pada bagian <a href="#unggah-bab">Unggah Bab</a>.</span></div>
<?php else: ?><p class="p2-line"><span>Naskah Bab 1–3 (format)</span><strong>Versi <?=(int)$formatDoc['versi']?> — <?=h(['menunggu_review'=>'Menunggu review Pembimbing 2','direvisi'=>'Perlu revisi format penulisan','disetujui'=>'Disetujui Pembimbing 2'][$formatDoc['status']]??$formatDoc['status'])?></strong></p><?php if($formatDoc['status']==='disetujui'&&!$proposalDoc): ?><div class="upload-lock" role="status"><strong>Langkah berikutnya</strong><span>Unggah proposal penelitian lengkap (Bab 1–3 beserta instrumen penelitian) pada bagian <a href="#unggah-bab">Unggah Bab</a> untuk disetujui Pembimbing 1.</span></div><?php endif; ?><?php endif; ?>
<?php if($proposalDoc): ?><p class="p2-line"><span>Proposal penelitian</span><strong>Versi <?=(int)$proposalDoc['versi']?> — <?=h(['menunggu_review'=>'Menunggu review Pembimbing 1','direvisi'=>'Perlu revisi','disetujui'=>'Disetujui Pembimbing 1'][$proposalDoc['status']]??$proposalDoc['status'])?></strong></p><?php endif; ?>
