<?php elseif($doneChapters<3): ?><div class="upload-lock" role="status"><strong>Belum dapat memilih Pembimbing 2</strong><span>Bab 1–3 yang sudah disetujui Pembimbing 1: <?=$doneChapters?> dari 3. Pilihan Pembimbing 2 terbuka setelah ketiganya disetujui.</span></div>
<?php elseif($proposalDoc): ?><p class="p2-line"><span>Pembimbing 2</span><strong>Tidak dipilih</strong></p><p class="p2-line"><span>Proposal penelitian</span><strong>Versi <?=(int)$proposalDoc['versi']?> — <?=h(['menunggu_review'=>'Menunggu review Pembimbing 1','direvisi'=>'Perlu revisi','disetujui'=>'Disetujui Pembimbing 1'][$proposalDoc['status']]??$proposalDoc['status'])?></strong></p>
<?php else: ?>
